def main():
    print("=" * 70)
    print("DogFitness - _update.py - RUNDA 2")
    print("=" * 70)

    if not os.path.exists(os.path.join(BASE_DIR, "manage.py")):
        print("!! UWAGA: nie znaleziono 'manage.py' w tym folderze.")
        print("   Uruchom ten skrypt z GLOWNEGO folderu projektu Django")
        print("   (tam gdzie jest plik manage.py).")
        answer = input("   Czy chcesz kontynuowac mimo to? (tak/nie): ").strip().lower()
        if answer not in ("tak", "t", "yes", "y"):
            print("Przerwano.")
            sys.exit(1)

    backed_up_any = False

    for rel_path, content in FILES.items():
        full_path = os.path.join(BASE_DIR, rel_path.replace("/", os.sep))
        dir_path = os.path.dirname(full_path)

        if not os.path.exists(dir_path):
            os.makedirs(dir_path, exist_ok=True)
            print(f"[+] Utworzono folder: {dir_path}")

        if os.path.exists(full_path):
            backup_target = os.path.join(BACKUP_DIR, rel_path.replace("/", os.sep))
            os.makedirs(os.path.dirname(backup_target), exist_ok=True)
            shutil.copy2(full_path, backup_target)
            backed_up_any = True

        with open(full_path, "w", encoding="utf-8") as f:
            f.write(content)
        print(f"[OK] Zapisano: {rel_path}")

    print("-" * 70)
    if backed_up_any:
        print(f"Kopie zapasowe nadpisanych plikow zapisano w:")
        print(f"  {BACKUP_DIR}")
    else:
        print("Nie bylo plikow do zbackupowania (wszystkie byly nowe).")

    print("-" * 70)
    print("GOTOWE! Nastepne kroki:")
    print("  1. python manage.py makemigrations")
    print("  2. python manage.py migrate")
